#!/usr/bin/env python3
"""Publish the generated public directory to the gh-pages branch."""

import os
from pathlib import Path
import shutil
import subprocess
import sys
import tempfile
import uuid


BRANCH = "gh-pages"
COMMIT_TRAILER = (
    "This commit was generated by the deploy.py script in the games-list repository."
)


def git(repository, *arguments, check=True, capture_output=False):
    return subprocess.run(
        ["git", "-C", str(repository), *arguments],
        check=check,
        capture_output=capture_output,
        text=True,
    )


def git_output(repository, *arguments):
    return git(repository, *arguments, capture_output=True).stdout.strip()


def clear_worktree(worktree):
    for path in worktree.iterdir():
        if path.name == ".git":
            continue
        if path.is_dir() and not path.is_symlink():
            shutil.rmtree(path)
        else:
            path.unlink()


def copy_site(public_directory, worktree):
    for path in public_directory.iterdir():
        destination = worktree / path.name
        if path.is_dir() and not path.is_symlink():
            shutil.copytree(path, destination, symlinks=True)
        elif path.is_symlink():
            destination.symlink_to(os.readlink(path))
        else:
            shutil.copy2(path, destination)


def git_identity(repository, key, environment_variable, fallback):
    value = os.environ.get(environment_variable)
    if value:
        return value
    result = git(repository, "config", "--get", key, check=False, capture_output=True)
    return result.stdout.strip() if result.returncode == 0 else fallback


def main():
    repository = Path(
        git_output(Path.cwd(), "rev-parse", "--show-toplevel")
    ).resolve()
    public_directory = repository / "public"
    if not (public_directory / "index.html").is_file():
        raise RuntimeError(
            "public/index.html is missing; build the Hugo site before deploying."
        )

    (public_directory / ".nojekyll").touch()
    remote = os.environ.get("DEPLOY_REMOTE", "origin")
    git_output(repository, "remote", "get-url", remote)

    branch_lookup = git(
        repository,
        "ls-remote",
        "--exit-code",
        remote,
        f"refs/heads/{BRANCH}",
        check=False,
        capture_output=True,
    )
    if branch_lookup.returncode not in (0, 2):
        raise subprocess.CalledProcessError(
            branch_lookup.returncode,
            branch_lookup.args,
            output=branch_lookup.stdout,
            stderr=branch_lookup.stderr,
        )
    branch_exists = branch_lookup.returncode == 0

    deploy_identity = uuid.uuid4().hex[:10]
    orphan_branch = None
    worktree_added = False

    with tempfile.TemporaryDirectory(prefix="games-list-deploy-") as temporary:
        worktree = Path(temporary) / "gh-pages"
        try:
            if branch_exists:
                git(repository, "fetch", "--no-tags", "--depth=1", remote, BRANCH)
                target = git_output(repository, "rev-parse", "FETCH_HEAD")
                git(repository, "worktree", "add", "--detach", str(worktree), target)
                worktree_added = True
            else:
                head = git_output(repository, "rev-parse", "HEAD")
                git(repository, "worktree", "add", "--detach", str(worktree), head)
                worktree_added = True
                orphan_branch = f"deploy-gh-pages-{deploy_identity}"
                git(worktree, "switch", "--orphan", orphan_branch)

            clear_worktree(worktree)
            copy_site(public_directory, worktree)
            git(worktree, "add", "--all")

            staged_changes = git(
                worktree, "diff", "--cached", "--quiet", check=False
            )
            if staged_changes.returncode == 0:
                print("The gh-pages branch is already up to date.")
                return
            if staged_changes.returncode != 1:
                raise subprocess.CalledProcessError(
                    staged_changes.returncode, staged_changes.args
                )

            name = git_identity(
                repository,
                "user.name",
                "GIT_AUTHOR_NAME",
                "github-actions[bot]",
            )
            email = git_identity(
                repository,
                "user.email",
                "GIT_AUTHOR_EMAIL",
                "41898282+github-actions[bot]@users.noreply.github.com",
            )
            message = os.environ.get("DEPLOY_COMMIT_MESSAGE", "Deploy site")
            message = f"{message}\n\n{COMMIT_TRAILER}"
            git(
                worktree,
                "-c",
                f"user.name={name}",
                "-c",
                f"user.email={email}",
                "commit",
                "-m",
                message,
            )
            git(worktree, "push", remote, f"HEAD:refs/heads/{BRANCH}")
            print(f"Published public/ to {remote}/{BRANCH}.")
        finally:
            if worktree_added:
                git(
                    repository,
                    "worktree",
                    "remove",
                    "--force",
                    str(worktree),
                )
            if orphan_branch:
                git(repository, "branch", "-D", orphan_branch)


if __name__ == "__main__":
    try:
        main()
    except (OSError, RuntimeError, subprocess.CalledProcessError) as error:
        print(f"Deployment failed: {error}", file=sys.stderr)
        sys.exit(1)
